public void initFromFreeItemLine(
    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine _crtFreeItemLine,
    GUPFreeItemLine _gupFreeItemLine)
{
    this.IsFreeItemLine = NoYes::Yes;
    this.GUPFreeItemLineRecId = _gupFreeItemLine.RecId;
    this.DisplayProductNumber = _crtFreeItemLine.ItemId;
    this.Product = _gupFreeItemLine.Product;
    this.Variant = _gupFreeItemLine.Variant;
    if (this.Variant)
    {
        this.DisplayProductVariantNumber = InventDimCombination::findByDistinctProductVariant(this.Variant).RetailVariantId;
    }

    this.updateFromCRTFreeItemLine(_crtFreeItemLine, _gupFreeItemLine);
}

public boolean updateFromCRTFreeItemLine(
    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine _crtFreeItemLine,
    GUPFreeItemLine _gupFreeItemLine)
{
    this.UoM = _gupFreeItemLine.UnitOfMeasure;
    this.Quantity = _crtFreeItemLine.Quantity * _crtFreeItemLine.QuantityFactor;
    if (_crtFreeItemLine.PriceUnit)
    {
        this.SalesPrice = _crtFreeItemLine.Price/_crtFreeItemLine.PriceUnit;
    }
    else
    {
        this.SalesPrice = _crtFreeItemLine.Price;
    }
    this.OriginalPrice = this.SalesPrice;
    this.DiscountAmount = this.SalesPrice;

    if (this.Quantity != this.orig().Quantity
        || this.UoM != this.orig().UoM
        || this.SalesPrice != this.orig().SalesPrice
        || this.DiscountAmount != this.orig().DiscountAmount)
    {
        return true;
    }

    return false;
}
